function s(){const e=document.querySelector('[data-section="trust-bar"]');if(!e)return;const a=e.querySelectorAll("[data-marquee] a");a.forEach(o=>{o.addEventListener("mouseenter",()=>{a.forEach(t=>t!==o&&t.classList.add("opacity-40"))}),o.addEventListener("mouseleave",()=>{a.forEach(t=>t.classList.remove("opacity-40"))})});const r=e.querySelector("[data-marquee-track]");r&&(e.addEventListener("mouseenter",()=>r.style.setProperty("animation-play-state","paused")),e.addEventListener("mouseleave",()=>r.style.setProperty("animation-play-state","running")))}export{s as initTrustBar};
